func TestMultipleGroupSamePathMiddleware(t *testing.T) {
	e := New()
	buf := new([]byte)
	_ = buf

	// echo-level middleware
	e.Use(func(next HandlerFunc) HandlerFunc {
		return func(c Context) error {
			c.Response().Header().Add("X-Echo", "1")
			return next(c)
		}
	})

	h := func(c Context) error {
		return c.NoContent(http.StatusOK)
	}

	g1 := e.Group("/api")
	g1.Use(func(next HandlerFunc) HandlerFunc {
		return func(c Context) error {
			c.Response().Header().Add("X-MW", "g1")
			return next(c)
		}
	})
	g1.GET("/one", h)

	g2 := e.Group("/api")
	g2.Use(func(next HandlerFunc) HandlerFunc {
		return func(c Context) error {
			c.Response().Header().Add("X-MW", "g2")
			return next(c)
		}
	})
	g2.GET("/two", h)

	_, _, rec := requestWithHeaders(http.MethodGet, "/api/one", e)
	assert.Equal(t, http.StatusOK, rec.Code)
	assert.Equal(t, []string{"g1"}, rec.Header()["X-Mw"], "route on g1 must only run g1 middleware")
	assert.Equal(t, []string{"1"}, rec.Header()["X-Echo"])

