// zzMatch mimics echo's routing semantics for a single route pattern.
func zzMatch(pattern, path string) bool {
	rest := path
	i := 0
	for i < len(pattern) {
		switch pattern[i] {
		case ':':
			if rest == "" {
				return false
			}
			j := strings.IndexByte(rest, '/')
			if j < 0 {
				rest = ""
			} else {
				rest = rest[j:]
			}
			k := i + 1
			for k < len(pattern) && pattern[k] != '/' {
				k++
			}
			i = k
		case '*':
			return true
		default:
			k := i
			for k < len(pattern) && pattern[k] != ':' && pattern[k] != '*' {
				k++
			}
			lit := pattern[i:k]
			if !strings.HasPrefix(rest, lit) {
				return false
			}
			rest = rest[len(lit):]
			i = k
		}
	}
	return rest == ""
}

